/////////////////////////////////	 TrendReaderV0.cpp : release 27.02.2004///////////////////////////////#include "TrendReaderV0.h"#include "Names.h"#include "CommProc.h"#include "BaseInt.h"#include "BaseType.h"#include "SysDataTypes.h"#include "Common.h"#include <stdlib.h>#include "TrendReaderImpl.h"extern HWND g_hWnd;extern int  b_hWnd;inline void Wnd(int n)  {  b_hWnd = n;  if ( ::IsWindowVisible(g_hWnd) )    ::InvalidateRect(g_hWnd,NULL,TRUE);  }//------------------------------------------------//  это для QueueUserAPC()VOID CALLBACK APCProc(ULONG_PTR dwParam){}//------------------------------------------------CTrendReader::CTrendReader(){	m_hCurrentWaitedPipeHandle	= INVALID_HANDLE_VALUE;	memset(m_trendPipeName,0,128);  }//////////////////////////////////////////////////CTrendReader::~CTrendReader()  {  StopServer();  }//////////////////////////////////////////////////void CTrendReader::StartServer()  {	//	lstrcpy(m_trendPipeName,"\\\\.\\pipe\\");  lstrcat(m_trendPipeName,NAME_PIPE_TRENDS);	//+++++++++++++++++++++++++++++++++++++++++++++	m_isStopClientService	= false;	m_isTrendServiceStop	= false;	m_hTrendServiceThread	= NULL;	// напустим тред на клиентский аsk	m_hTrendServiceThread	= AfxBeginThread((AFX_THREADPROC)StartMainLoop,(LPVOID)this);  }//////////////////////////////////////////////////void CTrendReader::StopServer(void)  {	//terminate main loop	m_isTrendServiceStop = true;	m_isStopClientService = true; 	// выведем main thread из блокa	на последнем(без клиента) объекте pipe	if (m_hCurrentWaitedPipeHandle!=INVALID_HANDLE_VALUE)	{ 		// associate IO port with pipe hndl		DWORD		CompletionKey=10;		HANDLE		hCompPort1 = CreateIoCompletionPort( INVALID_HANDLE_VALUE,NULL,CompletionKey,PIPE_UNLIMITED_INSTANCES);		HANDLE		hCompPort2 = CreateIoCompletionPort( m_hCurrentWaitedPipeHandle,hCompPort1,CompletionKey,PIPE_UNLIMITED_INSTANCES);		// kick input		DWORD		NumberOfBytes;		ULONG		CompletionKey1; 		OVERLAPPED	Overlapped;		OVERLAPPED* pOverlapped = &Overlapped;		DWORD		dwMilliseconds=500;				BOOL pS = GetQueuedCompletionStatus(hCompPort2,&NumberOfBytes,(PULONG_PTR)&CompletionKey1,&pOverlapped,dwMilliseconds); 				// terminate pipe object		DisconnectNamedPipe(m_hCurrentWaitedPipeHandle);		CloseHandle(m_hCurrentWaitedPipeHandle);		m_hCurrentWaitedPipeHandle=INVALID_HANDLE_VALUE;		CloseHandle(hCompPort1);		Sleep(100);	}  }//////////////////////////////////////////////////UINT	CTrendReader::StartMainLoop( LPVOID lpParam ){  	((CTrendReader*)lpParam)->MainLoop(lpParam);	return 0;}//////////////////////////////////////////////////UINT   CTrendReader::MainLoop( LPVOID lpParam ){	DWORD	inBufSize    = sizeof(SToTrend);	DWORD	outBufSize   = sizeof(SToTrend);	DWORD	clientTimeot = 1000;	m_isTrendServiceStop = false;	//=====	SECURITY_ATTRIBUTES sa;	SECURITY_DESCRIPTOR* psd;	psd = (SECURITY_DESCRIPTOR*) LocalAlloc(LPTR, SECURITY_DESCRIPTOR_MIN_LENGTH);	InitializeSecurityDescriptor(psd, SECURITY_DESCRIPTOR_REVISION);	SetSecurityDescriptorDacl(psd, TRUE, NULL, FALSE);	sa.nLength = sizeof(sa);	sa.lpSecurityDescriptor = psd;	sa.bInheritHandle = TRUE;	//====== MAIN SERVICE LOOP ========	params pPRM;	for ( ;!m_isTrendServiceStop; ) 	{ 	 		//# create pipe		HANDLE hTrendPipe = CreateNamedPipe( 									m_trendPipeName,             									PIPE_ACCESS_DUPLEX|FILE_FLAG_OVERLAPPED,       									PIPE_TYPE_MESSAGE | PIPE_READMODE_MESSAGE | PIPE_WAIT,                									PIPE_UNLIMITED_INSTANCES, 									outBufSize,									inBufSize,									clientTimeot,									&sa); 		if ( hTrendPipe == INVALID_HANDLE_VALUE) 		{			Sleep(100);			continue;			//break;   //?????????? выход из треда		}		//store last handle		m_hCurrentWaitedPipeHandle = hTrendPipe;				// wait client		BOOL isAsk   =  ConnectNamedPipe(hTrendPipe,NULL);			// выход по разблокировке(перед разбл выставить условие в false !!)		if(m_isTrendServiceStop) 		{			m_isStopClientService = true;			Sleep(100);			break;		}	  		// nice connect		if( isAsk )							{			CWinThread* pThread =NULL;//hTrendPipe			pPRM.pA=this;			pPRM.pH=hTrendPipe;			m_hTrendPipe = hTrendPipe;			m_hCurrentWaitedPipeHandle=INVALID_HANDLE_VALUE;			pThread = AfxBeginThread((AFX_THREADPROC)StartClientLoop,(LPVOID)&pPRM);			if (pThread != NULL) 			{				//m_clientThreadHandles.push_back(pThread);			}		}		else		{			//exit from bad session			DisconnectNamedPipe(hTrendPipe);			CloseHandle(hTrendPipe);		}	}//for pipe	return 0;} //////////////////////////////////////////////////UINT	CTrendReader::StartClientLoop( LPVOID lpParam1 )  {  params* pP=(params*)lpParam1;  ((CTrendReader*)(pP->pA))->ClientLoop((HANDLE)(pP->pH));  return 0;  }///////////////////////////////UINT CTrendReader::ClientLoop( HANDLE lpParam ){  HANDLE curPipeHandle = (HANDLE)lpParam;  //  m_isStopClientService = false;  KTrendReaderImpl reader( curPipeHandle, &m_isStopClientService );  reader.MainLoop();  DisconnectNamedPipe(curPipeHandle);   CloseHandle(curPipeHandle);  return 0;}